def comp(I):
    seen=[[False]*len(I[0]) for _ in I]; cids=[]
    for r in range(len(I)):
        for c in range(len(I[0])):
            if I[r][c] and not seen[r][c]:
                q=deque([(r,c)]); n=1; cells=[(r,c)]; seen[r][c]=True
                while q:
                    a,b=q.popleft()
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<len(I) and 0<=y<len(I[0]) and I[x][y] and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y)); n+=1; cells.append((x,y))
                cids.append((n,tuple(cells)))
    return cids
