    H=len(I);W=len(I[0])
    used=set(); tlist=[]
    changed=True
    while changed:
        changed=False
        for a in range(H-1):
            for b in range(W-1):
                cs=[(a+i,b+j) for i in(0,1) for j in(0,1)]
                if all(c in {(x,y) for x in cs} for c in cs) and all(I[c[0]][c[1]]==8 and c not in used for c in cs):
                    for c in cs: used.add(c)
                    tlist.append(('sq',cs)); changed=True; break
            if changed: break
        if not changed:
            done=False
            for a in range(H-1):
                for b in range(W-1):
                    cs=[(a+i,b+j) for i in(0,1) for j in(0,1)]
                    uc=[c for c in cs if c not in used]
                    if sum(I[c[0]][c[1]]==8 for c in uc)==3:
                        used|=set(cs); tlist.append(('L',cs)); done=True; break
                if done: break
    return tlist
