import collections, itertools
def feats_all(I,O):
    H=len(I);W=len(I[0])
    F={}
    for r in range(H):
        for c in range(W):
            if I[r][c]!=8: continue
            # square membership
            in_sq=False; complete=False; members=[]
            for a,b in itertools.product(range(H-1),range(W-1)):
                win={(a+i,b+j) for i in(0,1) for j in(0,1)}
                if (r,c) in win:
                    if all(I[x][y]==8 for x,y in win): in_sq=True
                    elif sum(I[x][y]==8 for x,y in win)==3: complete=True; members.append((a,b,'missing'))
            # role in completed square: which corner
            role=None
            for a,b in itertools.product(range(H-1),range(W-1)):
                win={(a+i,b+j) for i in(0,1) for j in(0,1)}
                if (r,c) in win and all(I[x][y]==8 for x,y in win-{(r,c)}):
                    # corner index within window: (dr,dc) of (r,c) rel to (a,b)
                    dr=r-a; dc=c-b
                    role=(dr,dc)
            F[(r,c)]=(in_sq,complete,members,role)
    return F
